import numpy as np
from scipy.optimize import least_squares
y=dA_dt
T=[np.ones_like(t),t,t**2]
def fitlin(cols):
    X=np.column_stack(cols)
    c=np.linalg.lstsq(X,y,rcond=None)[0]
    return np.mean((y-X@c)**2)/np.var(y), c
def m_rat(K):
    return [A/(1+K*A)*f for f in T]+[1/A*f for f in T]+[f for f in T[:2]]+[A*f for f in T[:2]]
def m_rat2(K):
    return [A/(1+K*A)*f for f in T]+[A**2/(1+K*A)*f for f in T]+[1/A*f for f in T]+[f for f in T[:2]]
def m_rat3(K):
    return [A/(K+A)*f for f in T]+[A**2/(K+A)*f for f in T]+[A*f for f in T[:2]]+[f for f in T[:1]]
for name,m in [('rat',m_rat),('rat2',m_rat2),('rat3',m_rat3)]:
    best=None
    for K in np.linspace(0.05,5,100):
        e,c=fitlin(m(K))
        if best is None or e<best[0]: best=(e,K)
    # refine
    r=least_squares(lambda q: y-np.column_stack(m(q[0]))@np.linalg.lstsq(np.column_stack(m(q[0])),y,rcond=None)[0], [best[1]])
    print(name,best,r.x, np.mean(r.fun**2)/np.var(y))

